use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use std::sync::Arc;
use std::ptr;
use std::fs;
use std::io::Write;

/// Custom allocator wrapper that logs allocations to a file for debugging
struct TracingBuffer {
    data: *mut u8,
    len: usize,
    capacity: usize,
}

impl TracingBuffer {
    fn new(size: usize) -> Self {
        let layout = std::alloc::Layout::from_size_align(size, 8).unwrap();
        let data = unsafe { std::alloc::alloc(layout) };
        if data.is_null() {
            std::alloc::handle_alloc_error(layout);
        }
        // Log allocation to crash dump file
        if let Ok(mut f) = fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open("/tmp/alloc_trace.log") {
            let _ = writeln!(f, "ALLOC: {:p} size={}", data, size);
        }
        TracingBuffer { data, len: 0, capacity: size }
    }

    fn write_bytes(&mut self, bytes: &[u8]) {
        let copy_len = bytes.len().min(self.capacity - self.len);
        unsafe {
            ptr::copy_nonoverlapping(bytes.as_ptr(), self.data.add(self.len), copy_len);
        }
        self.len += copy_len;
    }

    fn free(&mut self) {
        if !self.data.is_null() {
            let layout = std::alloc::Layout::from_size_align(self.capacity, 8).unwrap();
            unsafe { std::alloc::dealloc(self.data, layout); }
            // BUG: does NOT set self.data to null after dealloc
            // Log deallocation
            if let Ok(mut f) = fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open("/tmp/alloc_trace.log") {
                let _ = writeln!(f, "DEALLOC: {:p}", self.data);
            }
        }
    }
}

impl Drop for TracingBuffer {
    fn drop(&mut self) {
        // Drop calls free - if free() was already called manually,
        // this is a double-free
        self.free();
    }
}

async fn process_upload(body: web::Bytes) -> HttpResponse {
    let mut buffer = TracingBuffer::new(body.len().max(64));
    buffer.write_bytes(&body);

    // "Optimization": eagerly free if payload looks like a keepalive ping
    if body.len() < 4 || &body[..4] == b"PING" {
        buffer.free(); // First free here
        // buffer goes out of scope -> Drop -> second free (double-free!)
        return HttpResponse::Ok().body("pong");
    }

    // Process the data
    let result = format!("Processed {} bytes", buffer.len);
    // Normal path: single free via Drop
    HttpResponse::Ok().body(result)
}

async fn health() -> HttpResponse {
    HttpResponse::Ok().body("ok")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    println!("Starting upload service on :8080");

    HttpServer::new(|| {
        App::new()
            .route("/upload", web::post().to(process_upload))
            .route("/health", web::get().to(health))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
